/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parse, recompose, resolve, truncatedPercent } from './uri.js'

class RecordError extends Error {}

/** Split the input into records, dropping the empty tail a final newline leaves. */
export function split(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkPercent(uri) {
  const component = truncatedPercent(uri)
  if (component !== undefined) {
    throw new RecordError(`the ${component} has a truncated percent-encoding`)
  }
}

/** The output line for one record, or a `RecordError` describing its failure. */
function convert(mode, record) {
  if (mode === 'normalize') {
    const uri = parse(record)
    checkPercent(uri)
    return recompose(normalize(uri))
  }
  const space = record.indexOf(' ')
  if (space < 0) throw new RecordError('expected a base and a reference')
  const base = parse(record.slice(0, space))
  if (base.scheme === undefined) throw new RecordError('the base has no scheme')
  checkPercent(base)
  const reference = parse(record.slice(space + 1))
  checkPercent(reference)
  return recompose(resolve(base, reference))
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    return { err: 'error: usage: cli.js normalize|resolve\n' }
  }

  const records = split(readFileSync(0, 'utf8'))
  const out = []
  for (let i = 0; i < records.length; i += 1) {
    try {
      out.push(`${convert(mode, records[i])}\n`)
    } catch (error) {
      if (!(error instanceof RecordError)) throw error
      return { err: `error: line ${i + 1}: ${error.message}\n` }
    }
  }
  return { out: out.join('') }
}

const result = main(process.argv.slice(2))
if (result.err !== undefined) {
  process.stderr.write(result.err)
  process.exitCode = 2
} else if (result.out.length > 0) {
  process.stdout.write(result.out)
}
